<template>
  <div class="ops-lab knowledge-lab" :class="{ 'quiet-motion': quietHandoff }">
    <div class="lab-caption"><span class="lab-overline">Knowledge Management</span><span>Knowledge for the question-answering assistant.</span></div>
    <div class="knowledge-toolbar">
      <div class="knowledge-tabs" aria-label="Explore knowledge management">
        <button type="button" :aria-pressed="mode !== 'monitor'" @click="changeMode(acquisitionStarted ? 'acquire' : 'questions')">Find missing knowledge</button>
        <button type="button" :aria-pressed="mode === 'monitor'" @click="changeMode('monitor')">Monitor sources</button>
      </div>
      <span v-if="mode === 'monitor'" class="library-count">{{ monitorRegistry.length }} tracked sources</span>
    </div>

    <div v-if="mode === 'questions'" ref="questionWorkbench" class="knowledge-workbench" :class="{ 'gathering-gaps': collecting }">
      <section ref="matrix" class="coverage-desk" aria-label="Needs and knowledge coverage">
        <div class="coverage-matrix">
          <div></div><span class="matrix-column">Covered</span><span class="matrix-column">Missing</span>
          <span class="matrix-row">Known</span>
          <button type="button" class="matrix-case" :class="{ selected: question === 'hosting' }" :aria-pressed="question === 'hosting'" @click="selectQuestion('hosting')"><span class="case-purpose">Ready to answer</span><span>The library already has what someone asked for.</span><small>Explore <ArrowUpRightIcon /></small></button>
          <button ref="userGap" type="button" class="matrix-case uncovered" :class="{ selected: question === 'binding' }" :aria-pressed="question === 'binding'" @click="selectQuestion('binding')"><span class="case-purpose">{{ covered('binding') ? 'A gap the search filled' : 'An unanswered question' }}</span><span>{{ covered('binding') ? 'The search found evidence for this question.' : 'A question reveals information the library still needs.' }}</span><small>{{ covered('binding') ? 'Now supported' : 'Explore this gap' }} <ArrowUpRightIcon /></small></button>
          <span class="matrix-row">Latent</span>
          <button type="button" class="matrix-case latent" :class="{ selected: question === 'api' }" :aria-pressed="question === 'api'" @click="selectQuestion('api')"><span class="case-purpose">An unasked question</span><span>Existing material can answer a question nobody planned for.</span><small>Already covered <ArrowUpRightIcon /></small></button>
          <button ref="predictedGap" type="button" class="matrix-case uncovered latent prediction-cell" :class="{ selected: question === 'code', 'prediction-landed': predictionStage === 'complete' && !quietPrediction }" :aria-pressed="question === 'code'" :aria-busy="predicting" @click="predict"><span class="case-purpose"><SiteIcon name="spark" /> Predict a useful gap</span><span>{{ predicted ? 'Could renewal affect code that uses the certificate?' : predicting ? 'AI is considering a useful question…' : 'What else might someone need to know?' }}</span><small>{{ covered('code') ? 'Now supported' : predicted ? 'Explore this prediction' : predicting ? 'Predicting…' : 'Ask AI' }} <ArrowUpRightIcon /></small></button>
        </div>
        <p class="matrix-explanation">Known questions have been asked. Latent questions may matter before anyone asks.</p>
      </section>
      <section ref="answer" class="answer-desk" aria-label="What this part of the matrix means">
        <div class="coverage-explanation" aria-live="polite">
          <span class="case-coordinate">{{ coverageCase.label }}</span>
          <h4>{{ coverageCase.title }}</h4>
          <p>{{ coverageCase.explanation }}</p>
          <p class="case-outcome" :class="{ 'research-needed': coverageCase.drivesResearch }">{{ coverageCase.drivesResearch && answer ? 'This gap now has the evidence you accepted.' : coverageCase.outcome }}</p>
        </div>
        <div v-if="question === 'code' && (predicting || predicted)" class="prediction-preview" :class="{ 'prediction-thinking': predictionStage === 'thinking', 'prediction-quiet': quietPrediction }">
          <div class="prediction-heading"><span class="prediction-mark" aria-hidden="true"><SiteIcon name="spark" /></span><span>{{ predicting ? 'AI looks ahead' : 'AI suggested this question' }}</span></div>
          <div v-if="predictionStage === 'thinking'" class="prediction-context"><p>Looking at the knowledge already available…</p><div><span>Web apps</span><span>Certificate renewal</span></div><span class="prediction-dots" aria-hidden="true"><i></i><i></i><i></i></span></div>
          <div v-else ref="predictionCard" class="prediction-question" :class="{ 'question-in-flight': predictionStage === 'flying' }"><span>A possible next question</span><p>{{ questionText }}</p></div>
        </div>
        <div v-else-if="question !== 'code'" class="case-example"><span>For example</span><p class="selected-question">{{ questionText }}</p></div>
        <p v-else class="prediction-invitation">Select the prediction cell to watch AI suggest a question.</p>
        <details v-if="answer" :key="question" class="example-answer"><summary>Read the assistant’s answer</summary><p>{{ answer }}</p><div class="answer-citation"><span>Source</span><span>{{ answerSource.title }}</span></div></details>
      </section>
      <div class="gap-collection">
        <button type="button" class="collect-button" :disabled="collecting" @click="startAcquisition">
          <span ref="collector" class="collection-well" :class="{ received: collectedInputs > 0 }" aria-hidden="true"><svg v-if="!collectedInputs" viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="5.5" /><path d="m15 15 5 5" /></svg><span v-else :key="collectedInputs"><SiteIcon v-if="collectedInputs === 2" name="check" /><template v-else>1</template></span></span>
          <span>{{ collecting ? collectedInputs === 2 ? 'Both gaps gathered' : 'Bringing the gaps together…' : acquisitionBusy ? 'Return to the search' : 'Find supporting knowledge' }}</span><span class="collection-arrow" aria-hidden="true"><ArrowUpRightIcon /></span>
        </button>
      </div>
      <div class="gap-flight-layer" aria-hidden="true"><div v-for="flight in collectionFlights" :key="flight.id" ref="flights" class="gap-flight" :style="flightStyle(flight)"><span>{{ flight.label }}</span><strong>{{ flight.title }}</strong></div></div>
      <div class="gap-flight-layer" aria-hidden="true"><div v-if="predictionFlight" ref="predictionFlight" class="prediction-flight prediction-question" :style="flightStyle(predictionFlight)"><span>AI prediction</span><p>{{ questionText }}</p></div></div>
    </div>

    <div v-else-if="mode === 'acquire'" class="acquisition-workbench">
      <section ref="researchFocus" class="research-focus" aria-label="Research objective for related knowledge gaps">
        <button type="button" class="text-action" @click="changeMode('questions')"><SiteIcon name="arrow-left" /> Back to the questions</button>
        <div class="research-inputs"><span>Questions people asked</span><span><SiteIcon name="spark" /> AI prediction</span></div>
        <div class="research-objective" :class="{ grouping: acquisitionStage === 'clustering' }">
          <span>{{ acquisitionStage === 'clustering' ? 'Finding the shared topic' : 'One research focus' }}</span>
          <p ref="researchTitle" class="research-focus-title" tabindex="-1">Renewing and using certificates</p><small>Azure App Service</small>
        </div>
        <KnowledgeSearchTrail :found-sources="foundSources" :stage="acquisitionStage" :reduced-motion="reducedMotion || quietHandoff" />
        <details class="research-questions"><summary>{{ activeGaps.length }} questions behind this search</summary><div class="query-cluster"><div v-for="gap in activeGaps" :key="gap.id" class="cluster-query"><span>{{ gap.origin }}</span><p>{{ gap.text }}</p><small v-if="acquisitionStage === 'complete'" :class="{ 'coverage-met': covered(gap.id) }">{{ covered(gap.id) ? 'Now supported' : 'Still needs accepted evidence' }}</small></div></div></details>
        <details class="research-notes"><summary>How the search develops</summary><p>Related questions form a shared objective, {{ objective.toLowerCase() }}. It guides a broader search while every original question remains a coverage requirement.</p><ol><li v-for="(note, index) in researchNotes" :key="index">{{ note }}</li></ol><p>The crawler prioritises relevance, authority, and new information. An uncovered question triggers another seed search. It finishes when the gaps have evidence and further pages add little useful material.</p><p>After approval, ingestion extracts, normalises, deduplicates, and chunks the material. The indexed knowledge stays linked to its accepted sources.</p></details>
      </section>
      <section ref="research" class="research-results" aria-label="Sources found for the research objective">
        <div class="answer-heading"><span class="agent-star" :class="{ 'is-searching': acquisitionBusy }" aria-hidden="true"><SiteIcon name="spark" /></span><span>{{ acquisitionStage === 'complete' ? 'Added to the assistant’s knowledge' : acquisitionStage === 'review' ? 'Ready for your review' : 'Finding supporting knowledge' }}</span></div>
        <p class="research-status" aria-live="polite">{{ researchActivity }}</p>
        <div v-if="!foundSources.length" class="source-search-preview" aria-hidden="true"><span></span><i></i><i></i><small>Looking through documentation</small></div>
        <TransitionGroup name="activity" tag="div" class="discovered-sources"><div v-for="id in displayedSources" :key="id" class="research-source" :class="{ 'source-accepted': acquisitionStage === 'complete' && acceptedIds.includes(id) }"><label><input v-if="acquisitionStage === 'review'" v-model="chosenSources" type="checkbox" :value="id"><span v-else class="source-found-mark" aria-hidden="true"><SiteIcon :name="acquisitionStage === 'complete' && acceptedIds.includes(id) ? 'check' : 'document'" /></span><span><small>{{ source(id).authority }}</small><strong>{{ source(id).title }}</strong></span></label><p>{{ source(id).contribution }}</p><details><summary>Read the evidence</summary><p>{{ source(id).currentContent }}</p></details></div></TransitionGroup>
        <div v-if="acquisitionStage === 'review'" class="source-review-actions"><button type="button" class="lab-primary" :disabled="!chosenSources.length" @click="approveAcquisition">Accept {{ chosenSources.length || 'selected' }} {{ chosenSources.length === 1 ? 'source' : 'sources' }} <ArrowUpRightIcon /></button><button type="button" class="quiet-button" @click="declineAcquisition">Leave these out</button></div>
        <div v-if="acquisitionStage === 'complete'" class="accepted-result"><p>Accepted sources stay linked to the knowledge so changes can be monitored.</p><button type="button" class="text-action" @click="tryAcceptedAnswer">Try the assistant’s answer <ArrowUpRightIcon /></button><button type="button" class="text-action" @click="changeMode('monitor')">Try source monitoring <ArrowUpRightIcon /></button></div>
        <button v-if="acquisitionStage === 'declined'" type="button" class="lab-secondary" @click="startAcquisition">Try the research again <ArrowUpRightIcon /></button>
      </section>
    </div>

    <div v-else class="monitoring-workbench">
      <section class="registry-desk" aria-label="Source Registry">
        <div class="registry-heading"><span class="panel-eyebrow">Source Registry</span><p>The original links behind the knowledge.</p></div>
        <div class="registry-list"><button v-for="record in monitorRegistry" :key="record.id" type="button" :aria-pressed="monitoredId === record.id" :disabled="monitorBusy" @click="selectSource(record.id)"><span class="registry-record-top"><strong>{{ source(record.id).title }}</strong><small>{{ record.status }}</small></span><span class="registry-url">{{ source(record.id).url }}</span><span class="registry-record-bottom">{{ record.kbMappings.length }} linked KB {{ record.kbMappings.length === 1 ? 'entry' : 'entries' }}<span>{{ record.lastChecked }}</span></span></button></div>
      </section>
      <section ref="monitor" class="monitor-desk" aria-label="Check original source against accepted knowledge">
        <div class="answer-heading"><span class="monitor-symbol" aria-hidden="true"><SiteIcon name="monitor" /></span><span>Source monitoring</span><span class="coverage-indicator">{{ monitorStage === 'current' || monitorStage === 'applied' ? 'Current' : monitorStage === 'proposal' ? 'Your review' : 'Original source' }}</span></div>
        <p class="monitored-source">{{ monitoredSource.title }}</p>
        <div class="saved-knowledge"><span class="panel-eyebrow">{{ monitorStage === 'applied' ? 'Updated source version' : 'Saved source version' }}</span><p>{{ monitoredRecord.acceptedSnapshot }}</p></div>
        <button v-if="monitorStage === 'idle' || monitorStage === 'kept'" type="button" class="lab-primary" @click="runMonitor">Check the original source <ArrowUpRightIcon /></button>
        <p v-if="monitorBusy" class="monitor-progress" aria-live="polite">{{ monitorActivity }}</p>
        <div v-if="comparison && comparison.changed" class="retrieved-evidence"><span class="panel-eyebrow">Latest content at the same link</span><p>{{ comparison.retrieved }}</p></div>
        <div v-if="monitorStage === 'proposal'" class="agent-assessment"><span class="assessment-label"><SiteIcon name="spark" /> Agent assessment</span><p>The renewal guidance now includes conditions and certificate types missing from the saved version.</p><div class="proposed-mutation"><strong>Update the linked knowledge</strong></div><div class="refresh-actions"><button type="button" class="lab-primary" @click="approveRefresh">Accept the knowledge update <ArrowUpRightIcon /></button><button type="button" class="quiet-button" @click="keepKnowledge">Keep the current version</button></div></div>
        <div v-if="monitorStage === 'current'" class="monitor-resolution"><span aria-hidden="true"><SiteIcon name="check" /></span><p>The source still matches the saved version. No update needed.</p></div>
        <div v-if="monitorStage === 'applied'" class="monitor-resolution"><span aria-hidden="true"><SiteIcon name="check" /></span><p>The knowledge and saved source version are up to date.</p><button type="button" class="text-action" @click="runMonitor">Check the link again <ArrowUpRightIcon /></button></div>
        <p v-if="monitorStage === 'kept'" class="held-update">The existing knowledge and saved source version are unchanged.</p>
        <details class="monitor-details"><summary>What happens during a check</summary><p>Each registry record links an accepted source snapshot to the knowledge derived from it. The system revisits the original URL, extracts its main content, normalises it, and compares it with that snapshot. Only a content change reaches the agent.</p><p>The agent can propose replacement or deletion for human review. It can leave the KB unchanged when the difference is irrelevant, or return to discovery when more evidence is needed. Follow-up retrieval reaches review after it produces candidate sources.</p></details>
      </section>
    </div>
    <div class="knowledge-footer"><p class="knowledge-announcement" role="status">{{ notice }}</p><button type="button" class="quiet-button reset-experience" :class="{ 'reset-confirmed': resetAcknowledged }" aria-label="Reset experience" @click="reset"><span>{{ resetAcknowledged ? 'Experience reset' : 'Reset experience' }}</span><SiteIcon :name="resetAcknowledged ? 'check' : 'refresh'" /></button></div>
  </div>
</template>

<script>
import { coverageObjective, coverageCases, knowledgeGaps, sourceById, initialRegistry, gapIsCovered, commitSources, compareSource, assistantAnswer } from '../../data/itOpsKnowledge';
import KnowledgeSearchTrail from './KnowledgeSearchTrail.vue';
import '../../assets/css/it-ops-labs.css';

export default {
  name: 'ItOpsKnowledgeLab',
  components: { KnowledgeSearchTrail },
  data() {
    return {
      mode: 'questions', question: 'hosting', predicted: false, registry: initialRegistry(), objective: coverageObjective,
      // Each walkthrough retains its own state so acquisition cannot pre-resolve the monitoring example.
      monitorRegistry: initialRegistry(), resetAcknowledged: false,
      collecting: false, collectionFlights: [], collectedInputs: 0, reducedMotion: false, quietHandoff: false,
      predicting: false, predictionStage: 'idle', predictionFlight: null, quietPrediction: false,
      acquisitionStarted: false, acquisitionStage: 'idle', researchActivity: '', researchNotes: [], foundSources: [], chosenSources: [], acceptedIds: [],
      monitoredId: 'certificates', monitorStage: 'idle', monitorActivity: '', comparison: null, notice: '',
    };
  },
  computed: {
    coverageCase() { return coverageCases[this.question] || coverageCases.binding; },
    displayedSources() { return this.acquisitionStage === 'complete' ? this.foundSources.filter(id => this.acceptedIds.includes(id)) : this.foundSources; },
    activeGaps() { return knowledgeGaps.filter(gap => gap.origin !== 'AI prediction' || this.predicted); },
    acquisitionBusy() { return ['clustering', 'researching', 'ingesting'].includes(this.acquisitionStage); },
    answer() { return assistantAnswer(this.question, this.registry); },
    questionText() { return { renewal: 'Why did the certificate expire?', hosting: 'Can App Service host a Python web app?', api: 'Could the same platform host a REST API?', binding: 'Why is the renewed certificate not being served?', code: 'Could renewal affect code that uses the certificate?' }[this.question]; },
    answerSource() { return sourceById({ renewal: 'certificates', hosting: 'overview', api: 'overview', binding: 'bindings', code: 'certificate-code' }[this.question]); },
    monitoredRecord() { return this.monitorRegistry.find(record => record.id === this.monitoredId); },
    monitoredSource() { return sourceById(this.monitoredId); },
    monitorBusy() { return ['fetching', 'comparing', 'assessing', 'ingesting'].includes(this.monitorStage); },
  },
  mounted() {
    this._collectionRun = 0;
    this._collectionAnimations = [];
    this._predictionRun = 0;
    this._motionMedia = window.matchMedia('(prefers-reduced-motion: reduce)');
    this._onMotionChange = (event) => {
      this.reducedMotion = event.matches;
      if (event.matches && this.collecting) this.finishCollection(this._collectionRun);
      if (event.matches && this.predicting) this.finishPrediction(this._predictionRun);
    };
    this._onMotionChange(this._motionMedia);
    this._motionMedia.addEventListener?.('change', this._onMotionChange);
    this._onCollectionResize = () => {
      if (this.collecting) this.finishCollection(this._collectionRun);
      if (this.predicting) this.finishPrediction(this._predictionRun);
    };
    window.addEventListener('resize', this._onCollectionResize);
  },
  beforeUnmount() {
    this.clearTimers();
    this._motionMedia?.removeEventListener?.('change', this._onMotionChange);
    window.removeEventListener('resize', this._onCollectionResize);
  },
  methods: {
    source: sourceById,
    covered(id) { return gapIsCovered(id, this.registry); },
    clearTimers() { clearTimeout(this._researchTimer); clearTimeout(this._monitorTimer); clearTimeout(this._resetTimer); this.cancelCollection(); this.cancelPrediction(); },
    scrollPanel(name, immediate = false) {
      this.$nextTick(() => {
        if (window.innerWidth <= 700) this.$refs[name]?.scrollIntoView({ behavior: this.reducedMotion || immediate ? 'auto' : 'smooth', block: 'start' });
      });
    },
    changeMode(mode) { this.cancelCollection(); this.cancelPrediction(); this.mode = mode; },
    selectQuestion(question, immediate = false) { this.cancelCollection(); this.cancelPrediction(); this.question = question; this.scrollPanel('answer', immediate); },
    cancelPrediction() {
      this._predictionRun = (this._predictionRun || 0) + 1;
      clearTimeout(this._predictionTimer);
      this._predictionAnimation?.cancel(); this._predictionAnimation = null;
      this.predicting = false; this.predictionStage = 'idle'; this.predictionFlight = null;
    },
    finishPrediction(run) {
      if (!this.predicting || run !== this._predictionRun) return;
      this.cancelPrediction(); this.predicted = true; this.predictionStage = 'complete';
      this.notice = 'AI suggested a useful question and added it to the latent knowledge gap.';
    },
    predict(event) {
      if (this.predicting) return;
      this.selectQuestion('code', this.reducedMotion || !event?.detail);
      if (this.predicted) return;
      this.quietHandoff = false;
      this.quietPrediction = !event?.detail;
      this.predicting = true; this.predictionStage = 'thinking';
      const run = this._predictionRun;
      this.notice = 'AI is looking at existing knowledge for a useful question the library cannot answer yet.';
      if (this.reducedMotion || this.quietPrediction) { this.finishPrediction(run); this.scrollPanel('answer', true); return; }
      this._predictionTimer = setTimeout(() => {
        if (!this.predicting || run !== this._predictionRun) return;
        this.predictionStage = 'proposed';
        this._predictionTimer = setTimeout(() => this.flyPrediction(run), 650);
      }, 850);
    },
    async flyPrediction(run) {
      await this.$nextTick();
      if (!this.predicting || run !== this._predictionRun) return;
      const origin = this.$refs.predictionCard; const target = this.$refs.predictedGap; const canvas = this.$refs.questionWorkbench;
      if (!origin?.animate || !target || !canvas) { this.finishPrediction(run); return; }
      const rect = origin.getBoundingClientRect(); const destination = target.getBoundingClientRect(); const bounds = canvas.getBoundingClientRect();
      if (window.innerWidth <= 700 && destination.bottom > window.innerHeight - 24) {
        window.scrollBy?.({ top: destination.bottom - window.innerHeight + 24, behavior: 'smooth' });
      }
      this.predictionFlight = { x: rect.left - bounds.left, y: rect.top - bounds.top, width: rect.width, height: rect.height };
      this.predictionStage = 'flying';
      await this.$nextTick();
      if (!this.predicting || run !== this._predictionRun) return;
      const dx = destination.left + destination.width / 2 - rect.left - rect.width / 2;
      const dy = destination.top + destination.height / 2 - rect.top - rect.height / 2;
      const scale = Math.min(destination.width / rect.width, destination.height / rect.height);
      try {
        this._predictionAnimation = this.$refs.predictionFlight.animate([
          { transform: 'translate(0,0) rotate(0) scale(1)', opacity: 1 },
          { transform: `translate(${dx * .4}px,${dy * .4 - 15}px) rotate(-3deg) scale(.95)`, opacity: 1, offset: .4 },
          { transform: `translate(${dx}px,${dy}px) rotate(0) scale(${scale})`, opacity: 1, offset: .9 },
          { transform: `translate(${dx}px,${dy}px) rotate(0) scale(${scale})`, opacity: 0 },
        ], { duration: 740, easing: 'cubic-bezier(.4,0,.2,1)', fill: 'both' });
        await this._predictionAnimation.finished;
        this.finishPrediction(run);
      } catch {
        this.finishPrediction(run);
      }
    },
    laterResearch(fn, delay = 950) { clearTimeout(this._researchTimer); this._researchTimer = setTimeout(fn, delay); },
    flightStyle(flight) { return { left: `${flight.x}px`, top: `${flight.y}px`, width: `${flight.width}px`, height: `${flight.height}px` }; },
    cancelCollection() {
      this._collectionRun = (this._collectionRun || 0) + 1;
      clearTimeout(this._collectionTimer);
      (this._collectionAnimations || []).forEach(animation => animation.cancel());
      this._collectionAnimations = [];
      this.collectionFlights = [];
      this.collecting = false;
      this.collectedInputs = 0;
    },
    finishCollection(run) {
      if (!this.collecting || run !== this._collectionRun) return;
      this.cancelCollection();
      this.beginResearch();
    },
    async startAcquisition(event) {
      if (this.collecting) return;
      this.cancelPrediction();
      if (this.acquisitionBusy) { this.mode = 'acquire'; this.scrollPanel('researchFocus'); return; }
      this.predicted = true;
      this.quietHandoff = !event?.detail;
      const canvas = this.$refs.questionWorkbench;
      const collector = this.$refs.collector;
      const origins = [this.$refs.userGap, this.$refs.predictedGap];
      if (this.mode !== 'questions' || this.reducedMotion || this.quietHandoff || !canvas || !collector || origins.some(origin => !origin?.animate)) {
        this.beginResearch();
        return;
      }
      const run = this._collectionRun = (this._collectionRun || 0) + 1;
      this.collecting = true;
      this.notice = 'User questions and an AI-predicted gap are being gathered for the search.';
      await this.$nextTick();
      if (!this.collecting || run !== this._collectionRun) return;
      const bounds = canvas.getBoundingClientRect();
      const destination = collector.getBoundingClientRect();
      if (window.innerWidth <= 700 && (bounds.top < 72 || destination.bottom > window.innerHeight - 24)) {
        this.$refs.matrix?.scrollIntoView?.({ behavior: 'smooth', block: 'start' });
      }
      this.collectionFlights = origins.map((origin, index) => {
        const rect = origin.getBoundingClientRect();
        return {
          id: index, x: rect.left - bounds.left, y: rect.top - bounds.top, width: rect.width, height: rect.height,
          dx: destination.left + destination.width / 2 - rect.left - rect.width / 2,
          dy: destination.top + destination.height / 2 - rect.top - rect.height / 2,
          label: index ? 'AI prediction' : 'User questions',
          title: index ? 'Could renewal affect code that uses the certificate?' : 'Why is the old certificate still being served?',
        };
      });
      await this.$nextTick();
      if (!this.collecting || run !== this._collectionRun) return;
      const cards = this.$refs.flights || [];
      try {
        if (cards.length !== 2) { this.finishCollection(run); return; }
        cards.forEach((card, index) => {
          const flight = this.collectionFlights[index];
          const tilt = index ? 6 : -6;
          this._collectionAnimations.push(card.animate([
            { transform: 'translate(0, 0) scale(1) rotate(0deg)', opacity: 1, offset: 0 },
            { transform: `translate(-8px, -12px) scale(1.02) rotate(${tilt}deg)`, opacity: 1, offset: .18 },
            { transform: `translate(${flight.dx}px, ${flight.dy - 12}px) scale(.3) rotate(${-tilt / 2}deg)`, opacity: 1, offset: .86 },
            { transform: `translate(${flight.dx}px, ${flight.dy}px) scale(.18) rotate(0deg)`, opacity: 0, offset: 1 },
          ], { duration: 780, delay: index * 120, easing: 'cubic-bezier(.4,0,.2,1)', fill: 'both' }));
          this._collectionAnimations[index].finished.catch(() => {});
        });
        const arrivals = this._collectionAnimations.map(animation => animation.finished.then(() => {
          if (this.collecting && run === this._collectionRun) this.collectedInputs += 1;
        }).catch(() => {}));
        await Promise.all(arrivals);
        if (this.collecting && run === this._collectionRun) this._collectionTimer = setTimeout(() => this.finishCollection(run), 140);
      } catch {
        this.finishCollection(run);
      }
    },
    beginResearch() {
      clearTimeout(this._researchTimer);
      this.acquisitionStarted = true; this.mode = 'acquire'; this.acquisitionStage = 'clustering';
      this.foundSources = []; this.chosenSources = []; this.acceptedIds = []; this.researchNotes = [];
      this.researchActivity = 'Grouping related questions…'; this.notice = '';
      this.$nextTick(() => this.$refs.researchTitle?.focus({ preventScroll: true }));
      this.scrollPanel('researchFocus', this.quietHandoff);
      this.laterResearch(() => {
        this.acquisitionStage = 'researching'; this.researchActivity = 'Finding useful starting pages…';
        this.researchNotes.push('The related gaps form one certificate-lifecycle objective. Their individual coverage requirements are retained.');
        this.researchNotes.push('Seed discovery searches several facets, including renewal conditions and renewed-certificate bindings.');
        this.laterResearch(() => this.discoverSource(0));
      });
    },
    discoverSource(index) {
      const ids = ['certificates', 'bindings', 'certificate-code']; const id = ids[index];
      if (!id) {
        this.acquisitionStage = 'review'; this.chosenSources = [...this.foundSources];
        this.researchActivity = 'Choose what to add to the assistant’s knowledge.';
        this.researchNotes.push('The candidate sources cover the original questions. Further links add mostly duplicate or peripheral material, so the search can finish. The knowledge base still awaits approval.');
        return;
      }
      this.foundSources.push(id);
      this.researchActivity = index === 0 ? 'Renewal guidance found. Following the binding question…' : index === 1 ? 'The code question still needs evidence. Trying another starting page…' : 'Checking what these sources cover…';
      this.researchNotes.push(index === 0 ? 'Focused crawling extracts useful document content and uses source authority and new information to prioritise which links to follow.' : index === 1 ? 'An uncovered application-code question triggers targeted seed discovery in another branch.' : 'The application-code source adds certificate-loading and thumbprint considerations. Duplicate and off-topic links are excluded.');
      this.laterResearch(() => this.discoverSource(index + 1), index === 1 ? 1300 : 950);
    },
    tryAcceptedAnswer() { this.mode = 'questions'; this.selectQuestion(['binding', 'code', 'renewal'].find(id => this.covered(id)) || 'hosting'); },
    approveAcquisition() {
      if (!this.chosenSources.length || this.acquisitionStage !== 'review') return;
      this.acceptedIds = [...this.chosenSources]; this.acquisitionStage = 'ingesting';
      this.researchActivity = 'Adding approved material and saving its sources…';
      this.laterResearch(() => {
        this.registry = commitSources(this.registry, this.acceptedIds);
        this.acquisitionStage = 'complete'; this.researchActivity = 'The assistant can now use the accepted sources.';
        this.notice = 'The Knowledge Base and Source Registry were updated together after approval.';
      }, 1000);
    },
    declineAcquisition() { this.acquisitionStage = 'declined'; this.researchActivity = 'These sources were left out. The assistant’s knowledge is unchanged.'; },
    selectSource(id) { clearTimeout(this._monitorTimer); this.monitoredId = id; this.monitorStage = 'idle'; this.comparison = null; this.scrollPanel('monitor'); },
    runMonitor() {
      clearTimeout(this._monitorTimer); this.comparison = null; this.monitorStage = 'fetching'; this.monitorActivity = 'Revisiting the original source…';
      this._monitorTimer = setTimeout(() => {
        this.monitorStage = 'comparing'; this.monitorActivity = 'Comparing it with the saved version…';
        this._monitorTimer = setTimeout(() => {
          this.comparison = compareSource(this.monitoredRecord); this.monitoredRecord.lastChecked = 'Checked just now';
          if (!this.comparison.changed) { this.monitoredRecord.status = 'Active'; this.monitorStage = 'current'; this.notice = 'The source is unchanged. No knowledge update is needed.'; return; }
          this.monitoredRecord.status = 'Changed'; this.monitorStage = 'assessing'; this.monitorActivity = 'The page changed. Checking what this means for the knowledge…';
          this._monitorTimer = setTimeout(() => { this.monitorStage = 'proposal'; this.notice = 'An update is ready for review.'; }, 900);
        }, 650);
      }, 700);
    },
    approveRefresh() {
      if (this.monitorStage !== 'proposal') return;
      this.monitorStage = 'ingesting'; this.monitorActivity = 'Updating the knowledge and saved source version…'; const id = this.monitoredId;
      this._monitorTimer = setTimeout(() => { this.monitorRegistry = commitSources(this.monitorRegistry, [id]); this.monitorStage = 'applied'; this.comparison = null; this.notice = 'The approved knowledge update has been applied.'; }, 900);
    },
    keepKnowledge() { this.monitorStage = 'kept'; this.monitoredRecord.status = 'Needs review'; this.notice = 'The proposed change was not committed.'; },
    reset() {
      this.clearTimers(); this.mode = 'questions'; this.question = 'hosting'; this.predicted = false; this.registry = initialRegistry();
      this.acquisitionStarted = false; this.acquisitionStage = 'idle'; this.researchActivity = ''; this.researchNotes = [];
      this.foundSources = []; this.chosenSources = []; this.acceptedIds = []; this.monitoredId = 'certificates';
      this.monitorStage = 'idle'; this.comparison = null; this.monitorRegistry = initialRegistry(); this.quietHandoff = false; this.quietPrediction = false; this.notice = 'Experience reset.';
      this.resetAcknowledged = true;
      this._resetTimer = setTimeout(() => { this.resetAcknowledged = false; }, 1200);
    },
  },
};
</script>
